 {
  "ruta": "firewall-acl-agent/tests/unit/test_protegidos_antispoof.cpp",
  "antes": null,
  "despues": "96f7dab8722bc1628e776b5649247e000db5d7bebbca5235bb5f6fe5f82f1f4e",
  "nuevo_b64": null,
  "contenido": "// test_protegidos_antispoof.cpp -- [PROTEGIDOS-ANTISPOOF-D320] ADR-060 D8, 8e.4b: la parte pura del antispoofing (sin\n// kernel ni root): reparto en los sets con la comprobación de ruta (H-D), texto exacto de las reglas como lo imprime\n// 'iptables -S' (medido DAY320: --limit-burst 5 se omite), texto de iptables-restore en los dos modos, comprobación de\n// cadenas y sets, y el paso con wrappers falsos (solo cuenta como reconciliado lo que se vuelve a leer).\n#include \"firewall/protegidos_antispoof.hpp\"\n\n#include <algorithm>\n#include <iostream>\n#include <map>\n#include <optional>\n#include <string>\n#include <vector>\n\nusing namespace mldefender::firewall;\n\nstatic int g_total = 0;\nstatic int g_fallos = 0;\n#define CHECK(c)                                                            \\\n    do {                                                                    \\\n        ++g_total;                                                          \\\n        if (!(c)) {                                                         \\\n            ++g_fallos;                                                     \\\n            std::cerr << \"FALLA linea \" << __LINE__ << \": \" #c << std::endl; \\\n        }                                                                   \\\n    } while (0)\n\nstatic bool tiene(const std::string& s, const std::string& x) { return s.find(x) != std::string::npos; }\nstatic bool contiene(const std::vector<std::string>& v, const std::string& x) {\n    return std::find(v.begin(), v.end(), x) != v.end();\n}\n\n// Wrappers falsos: el \"kernel\" son mapas; restaurar_sin_vaciar deja las cadenas como se generan salvo si miente.\nstruct IpsFalso {\n    std::map<std::string, std::string> tipo;\n    std::map<std::string, std::vector<std::string>> cont;\n    bool mentirosa = false;\n    int reemplazos = 0;\n    std::optional<std::string> set_type(const std::string& s) const {\n        auto it = tipo.find(s);\n        return it == tipo.end() ? std::nullopt : std::optional<std::string>(it->second);\n    }\n    bool create_set(const IPSetConfig& c) {\n        static const char* t[] = {\"hash:ip\", \"hash:net\", \"hash:ip,port\", \"hash:net,iface\", \"hash:ip,mac\"};\n        tipo[c.name] = t[static_cast<int>(c.type)];\n        cont[c.name].clear();\n        return true;\n    }\n    std::vector<std::string> list_entries_opciones(const std::string& s) const {\n        auto it = cont.find(s);\n        return it == cont.end() ? std::vector<std::string>{} : it->second;\n    }\n    IPSetResult<void> replace_set(const std::string& s, IPSetType, const std::vector<std::string>& e, uint32_t) {\n        ++reemplazos;\n        if (!mentirosa) cont[s] = e;\n        return IPSetResult<void>();\n    }\n};\nstruct IptFalso {\n    std::map<std::string, std::vector<std::string>> reglas;\n    NombresAntispoof n;\n    bool descarta_al_restaurar = false, mentirosa = false;\n    int restauraciones = 0;\n    std::vector<std::string> list_rules(const std::string& ch, IPTablesTable) const {\n        auto it = reglas.find(ch);\n        return it == reglas.end() ? std::vector<std::string>{} : it->second;\n    }\n    IPTablesResult<void> restaurar_sin_vaciar(const std::string& texto) {\n        ++restauraciones;\n        if (!mentirosa) {\n            const bool d = tiene(texto, \"argus-spoof-if -j DROP\");\n            reglas[n.cadena] = reglas_esperadas_principal(n);\n            reglas[n.cadena + \"_IF\"] = reglas_esperadas_spoof(n, \"_IF\", \"ARGUS-SPOOF-IF \", d);\n            reglas[n.cadena + \"_MAC\"] = reglas_esperadas_spoof(n, \"_MAC\", \"ARGUS-SPOOF-MAC \", d);\n        }\n        return IPTablesResult<void>();\n    }\n    IPTablesResult<void> salto_en_primera(IPTablesTable, const std::string& base, const std::string& destino) {\n        if (!mentirosa) reglas[base] = {\"-A \" + base + \" -j \" + destino};\n        return IPTablesResult<void>();\n    }\n};\n\nint main() {\n    // ── reparto (H-D) ──\n    auto ruta_lab = [](const std::string& ip) { return ip.rfind(\"192.168.100.\", 0) == 0 ? std::string(\"eth2\") : std::string(\"eth0\"); };\n    {\n        const std::vector<EntradaAntispoof> e{{\"192.168.100.20/32\", \"eth2\", \"08:00:27:a2:00:20\"},\n                                              {\"192.168.100.61/32\", \"eth2\", \"\"},\n                                              {\"192.168.100.77/24\", \"eth2\", \"08:00:27:00:00:01\"},  // MAC en una /24: no\n                                              {\"10.9.0.0/24\", \"eth2\", \"\"}};                        // la ruta va por eth0\n        const auto r = repartir_antispoof(e, ruta_lab);\n        CHECK(r.redes.size() == 3 && contiene(r.redes, \"192.168.100.20/32\") && contiene(r.redes, \"192.168.100.0/24\"));\n        CHECK(!contiene(r.redes, \"10.9.0.0/24\") && r.sin_ruta.size() == 1 && tiene(r.sin_ruta[0], \"la ruta va por eth0\"));\n        CHECK(r.ips_mac.size() == 1 && r.ips_mac[0] == \"192.168.100.20\");\n        CHECK(r.mac.size() == 1 && r.mac[0] == \"192.168.100.20,08:00:27:a2:00:20\");\n    }\n    {   // host con dos interfaces legítimas: con que una case con la ruta, la red entra y no hay alarma\n        const std::vector<EntradaAntispoof> e{{\"192.168.100.30/32\", \"eth2\", \"\"}, {\"192.168.100.30/32\", \"eth3\", \"\"}};\n        const auto r = repartir_antispoof(e, ruta_lab);\n        CHECK(r.redes.size() == 1 && r.sin_ruta.empty());\n    }\n    {   // sin ruta conocida: fuera\n        const auto r = repartir_antispoof(std::vector<EntradaAntispoof>{{\"192.168.100.20/32\", \"eth2\", \"\"}},\n                                          [](const std::string&) { return std::string(); });\n        CHECK(r.redes.empty() && r.sin_ruta.size() == 1);\n    }\n    CHECK(repartir_antispoof(std::vector<EntradaAntispoof>{}, ruta_lab).redes.empty());\n\n    // ── texto de las reglas ──\n    NombresAntispoof n{\"ARGUS_ANTISPOOF\", \"ml_defender_prot_redes\", \"ml_defender_protegidos\", \"ml_defender_prot_ipmac\",\n                       \"ml_defender_prot_mac\", 5, 5, true};\n    const auto p = reglas_esperadas_principal(n);\n    CHECK(p.size() == 7 && p[0] == \"-N ARGUS_ANTISPOOF\" && p[1] == \"-A ARGUS_ANTISPOOF -i lo -j RETURN\");\n    CHECK(p.size() == 7 && p[3] == \"-A ARGUS_ANTISPOOF -m set ! --match-set ml_defender_protegidos src,src -g ARGUS_ANTISPOOF_IF\");\n    CHECK(p.size() == 7 && p[5] == \"-A ARGUS_ANTISPOOF -m set ! --match-set ml_defender_prot_mac src,src -g ARGUS_ANTISPOOF_MAC\");\n    CHECK(p.size() == 7 && p[6] == \"-A ARGUS_ANTISPOOF -j RETURN\");\n    const auto si = reglas_esperadas_spoof(n, \"_IF\", \"ARGUS-SPOOF-IF \", false);\n    CHECK(si[1] == \"-A ARGUS_ANTISPOOF_IF -m limit --limit 5/min -j LOG --log-prefix \\\"ARGUS-SPOOF-IF \\\"\");  // burst 5 omitido\n    CHECK(si[2] == \"-A ARGUS_ANTISPOOF_IF -m comment --comment argus-spoof-if\");\n    CHECK(reglas_esperadas_spoof(n, \"_IF\", \"ARGUS-SPOOF-IF \", true)[2] ==\n          \"-A ARGUS_ANTISPOOF_IF -m comment --comment argus-spoof-if -j DROP\");\n    {\n        NombresAntispoof n7 = n;\n        n7.log_por_minuto = 7;\n        n7.log_rafaga = 7;\n        CHECK(tiene(reglas_esperadas_spoof(n7, \"_MAC\", \"ARGUS-SPOOF-MAC \", false)[1], \"--limit 7/min --limit-burst 7\"));\n        NombresAntispoof nm = n;\n        nm.con_mac = false;\n        CHECK(reglas_esperadas_principal(nm).size() == 5);\n    }\n    const std::string tc = texto_restore_antispoof(n, false), td = texto_restore_antispoof(n, true);\n    CHECK(tiene(tc, \"*raw\\n:ARGUS_ANTISPOOF - [0:0]\\n:ARGUS_ANTISPOOF_IF - [0:0]\\n:ARGUS_ANTISPOOF_MAC - [0:0]\\n\"));\n    CHECK(tiene(tc, \"-g ARGUS_ANTISPOOF_IF\") && tiene(tc, \"-g ARGUS_ANTISPOOF_MAC\") && tiene(tc, \"-i lo -j RETURN\"));\n    CHECK(!tiene(tc, \"-j DROP\") && tiene(td, \"argus-spoof-if -j DROP\") && tiene(td, \"argus-spoof-mac -j DROP\"));\n    CHECK(tiene(tc, \"--limit-burst 5\") && tc.size() > 10 && tc.substr(tc.size() - 7) == \"COMMIT\\n\");\n\n    // ── comprobación de las cadenas ──\n    const std::vector<std::string> pre{\"-A PREROUTING -j ARGUS_ANTISPOOF\"};\n    const auto si_c = reglas_esperadas_spoof(n, \"_IF\", \"ARGUS-SPOOF-IF \", false);\n    const auto sm_c = reglas_esperadas_spoof(n, \"_MAC\", \"ARGUS-SPOOF-MAC \", false);\n    CHECK(comprobar_reglas_antispoof(pre, p, si_c, sm_c, n, false).empty());\n    CHECK(!comprobar_reglas_antispoof(pre, p, si_c, sm_c, n, true).empty());            // modo distinto\n    CHECK(!comprobar_reglas_antispoof({}, p, si_c, sm_c, n, false).empty());            // sin salto\n    CHECK(!comprobar_reglas_antispoof({\"-A PREROUTING -j X\", pre[0]}, p, si_c, sm_c, n, false).empty());  // pos 2\n    {\n        auto p2 = p;\n        p2.erase(p2.begin() + 1);  // sin la regla de lo\n        CHECK(!comprobar_reglas_antispoof(pre, p2, si_c, sm_c, n, false).empty());\n        auto p3 = p;\n        if (p3.size() < 4) p3.resize(4);\n        p3[3] = \"-A ARGUS_ANTISPOOF -m set ! --match-set ml_defender_protegidos src,src -j ARGUS_ANTISPOOF_IF\";  // -j\n        CHECK(!comprobar_reglas_antispoof(pre, p3, si_c, sm_c, n, false).empty());\n    }\n\n    // ── comprobación de sets ──\n    CHECK(set_cuadra({\"192.168.100.20\", \"192.168.100.0/24\"}, {\"192.168.100.20/32\", \"192.168.100.0/24\"}, true));\n    CHECK(!set_cuadra({\"192.168.100.20\", \"10.6.6.6\"}, {\"192.168.100.20/32\"}, true));\n    CHECK(!set_cuadra({\"192.168.100.20 nomatch\"}, {\"192.168.100.20/32\"}, true));\n    CHECK(set_cuadra({\"192.168.100.20,08:00:27:A2:00:20\"}, {\"192.168.100.20,08:00:27:a2:00:20\"}, false));  // mayúsculas\n    CHECK(!set_cuadra({\"192.168.100.20,08:00:27:A2:00:21\"}, {\"192.168.100.20,08:00:27:a2:00:20\"}, false));\n    CHECK(set_cuadra({}, {}, true));\n\n    // ── el paso con wrappers falsos ──\n    RepartoAntispoof rep;\n    rep.redes = {\"192.168.100.20/32\"};\n    rep.ips_mac = {\"192.168.100.20\"};\n    rep.mac = {\"192.168.100.20,08:00:27:a2:00:20\"};\n    {   // a) aplicar desde cero: crea los tres sets, carga cadenas y salto; reconciliado\n        IpsFalso ips;\n        IptFalso ipt;\n        ipt.n = n;\n        const auto r = antispoof_paso(ips, ipt, n, rep, false, 64, false);\n        CHECK(r.reconciliado && r.error.empty() && ips.tipo[\"ml_defender_prot_mac\"] == \"hash:ip,mac\" && ipt.restauraciones == 1);\n        // b) vigía sin cambios: nada\n        const auto r2 = antispoof_paso(ips, ipt, n, rep, false, 64, true);\n        CHECK(!r2.divergente && r2.reconciliado && ipt.restauraciones == 1);\n        // c) alguien borra una regla: divergencia y reconciliación\n        ipt.reglas[n.cadena].erase(ipt.reglas[n.cadena].begin() + 1);\n        const auto r3 = antispoof_paso(ips, ipt, n, rep, false, 64, true);\n        CHECK(r3.divergente && r3.reconciliado && ipt.restauraciones == 2);\n        // d) alguien mete una red en set_redes: divergencia y reconciliación\n        ips.cont[\"ml_defender_prot_redes\"].push_back(\"10.6.6.6\");\n        const auto r4 = antispoof_paso(ips, ipt, n, rep, false, 64, true);\n        CHECK(r4.divergente && r4.reconciliado && ips.cont[\"ml_defender_prot_redes\"].size() == 1);\n        // e) cambio de modo (cuenta -> descarta) detectado por el vigía\n        const auto r5 = antispoof_paso(ips, ipt, n, rep, true, 64, true);\n        CHECK(r5.divergente && r5.reconciliado && tiene(ipt.reglas[n.cadena + \"_IF\"][2], \"-j DROP\"));\n    }\n    {   // f) iptables dice \"hecho\" y no hace nada: NO reconciliado\n        IpsFalso ips;\n        IptFalso ipt;\n        ipt.n = n;\n        ipt.mentirosa = true;\n        const auto r = antispoof_paso(ips, ipt, n, rep, false, 64, false);\n        CHECK(!r.reconciliado && !r.error.empty());\n    }\n    {   // g) ipset dice \"hecho\" y no hace nada: NO reconciliado\n        IpsFalso ips;\n        ips.mentirosa = true;\n        IptFalso ipt;\n        ipt.n = n;\n        const auto r = antispoof_paso(ips, ipt, n, rep, false, 64, false);\n        CHECK(!r.reconciliado && !r.error.empty());\n    }\n    {   // h) set ajeno: no se destruye ni se instala la cadena que lo usaría\n        IpsFalso ips;\n        ips.tipo[\"ml_defender_prot_redes\"] = \"hash:ip\";\n        IptFalso ipt;\n        ipt.n = n;\n        const auto r = antispoof_paso(ips, ipt, n, rep, false, 64, true);\n        CHECK(r.divergente && !r.reconciliado && ips.tipo[\"ml_defender_prot_redes\"] == \"hash:ip\" && ipt.restauraciones == 0);\n    }\n    {   // i) sin hash:ip,mac: no se toca set_mac ni set_ips_mac\n        NombresAntispoof nm = n;\n        nm.con_mac = false;\n        IpsFalso ips;\n        IptFalso ipt;\n        ipt.n = nm;\n        const auto r = antispoof_paso(ips, ipt, nm, rep, false, 64, false);\n        CHECK(r.reconciliado && ips.tipo.count(\"ml_defender_prot_mac\") == 0 && ips.tipo.count(\"ml_defender_prot_ipmac\") == 0);\n    }\n\n    std::cout << \"test_protegidos_antispoof: \" << (g_total - g_fallos) << \"/\" << g_total << \" comprobaciones\" << std::endl;\n    return g_fallos == 0 ? 0 : 1;\n}\n",
  "modo": 420
 },
 {
  "ruta": "firewall-acl-agent/tests/unit/test_protegidos_antispoof_root.cpp",
  "antes": null,
  "despues": "f2eead563f6f494bef44bbd50358f8e07b9aafe47d84b0a84f26c51aef08d667",
  "nuevo_b64": null,
  "contenido": "// test_protegidos_antispoof_root.cpp -- [PROTEGIDOS-ANTISPOOF-D320] ADR-060 D8, 8e.4b: el antispoofing contra el KERNEL\n// real (la medida de DAY320, scripts/etcd_ha/d320_medir_antispoof.sh, hecha test con el código del agente). Requiere\n// root (make test-firewall-e2e). Sin root sale con 77 = Skipped. Sin hash:ip,mac en el kernel también sale con 77 (el\n// gate de test-firewall-e2e lo cuenta como fallo); ARGUS_TEST_SIN_IPMAC=1 lo corre sin la parte de MAC (solo banco).\n// Red de prueba: netns argas320 con veth as0 (raíz, 10.251.0.1/30) <-> as1 (netns, 10.251.0.2/30) y rutas /32 por as0\n// para .21 y .22. Entradas: .20 por la interfaz real de su ruta; .21 por as0 con una MAC que no es la de as1; .22 por\n// as0 con la MAC de as1; .23 por as0 sin ruta por as0 (H-D: fuera). Sets y cadenas propios del test; se limpia todo.\n//   A1 aplicar en modo cuenta y comprobar sin cambios      A6 .23 (sin ruta): no cuenta, y aparece en sin_ruta\n//   A2 no protegido: 0 spoofing                             A7 origen protegido por lo: exento\n//   A3 .20 por as0: SPOOF-IF +10                            A8 modo descarta: SPOOF-IF +10 y 0 llegan a mangle\n//   A4 .21 MAC distinta: SPOOF-MAC +10                      A9 alguien borra la regla de lo: divergencia y reconciliación\n//   A5 .22 interfaz y MAC buenas: 0                         A10 limpieza completa\n#include \"firewall/protegidos_antispoof.hpp\"\n\n#include <unistd.h>\n\n#include <cstdio>\n#include <cstdlib>\n#include <iostream>\n#include <string>\n#include <vector>\n\nusing namespace mldefender::firewall;\n\nstatic int g_total = 0;\nstatic int g_fallos = 0;\n#define CHECK(c)                                                            \\\n    do {                                                                    \\\n        ++g_total;                                                          \\\n        if (!(c)) {                                                         \\\n            ++g_fallos;                                                     \\\n            std::cerr << \"FALLA linea \" << __LINE__ << \": \" #c << std::endl; \\\n        }                                                                   \\\n    } while (0)\n\nstatic std::string sh(const std::string& cmd) {\n    std::string out;\n    FILE* p = ::popen((cmd + \" 2>&1\").c_str(), \"r\");\n    if (!p) return out;\n    char buf[512];\n    while (std::fgets(buf, sizeof(buf), p)) out += buf;\n    ::pclose(p);\n    return out;\n}\n\nstatic const std::string NS = \"argas320\", VA = \"as0\", VB = \"as1\";\nstatic const std::string CH = \"TAS320\";\nstatic const std::string S_RED = \"tas320_red\", S_IF = \"tas320_if\", S_IPM = \"tas320_ipm\", S_MAC = \"tas320_mac\";\nstatic const char* MAL_MAC = \"02:00:00:00:d3:20\";\n\nstatic void limpiar() {\n    sh(\"while iptables -w -t raw -D PREROUTING -j \" + CH + \" 2>/dev/null; do :; done\");\n    sh(\"iptables -w -t mangle -D PREROUTING -i \" + VA + \" -s 192.168.100.20 -m comment --comment tas320-llegan 2>/dev/null\");\n    for (const auto& c : {CH, CH + \"_IF\", CH + \"_MAC\"}) sh(\"iptables -w -t raw -F \" + c + \" 2>/dev/null\");\n    for (const auto& c : {CH, CH + \"_IF\", CH + \"_MAC\"}) sh(\"iptables -w -t raw -X \" + c + \" 2>/dev/null\");\n    for (const auto& s : {S_RED, S_IF, S_IPM, S_MAC}) sh(\"ipset destroy \" + s + \" 2>/dev/null; ipset destroy \" + s + \"_n 2>/dev/null\");\n    sh(\"ip netns del \" + NS + \" 2>/dev/null; ip link del \" + VA + \" 2>/dev/null\");\n    sh(\"ip route del 192.168.100.21/32 dev \" + VA + \" 2>/dev/null; ip route del 192.168.100.22/32 dev \" + VA + \" 2>/dev/null\");\n}\n\n// 10 paquetes UDP con origen 'src' hacia 10.251.0.1 desde el netns (o, con en_raiz, hacia 127.0.0.1 por lo).\nstatic void manda(const std::string& src, bool en_raiz = false) {\n    const std::string py =\n        \"import socket,struct,sys\\n\"\n        \"s=socket.socket(socket.AF_INET,socket.SOCK_RAW,socket.IPPROTO_RAW)\\n\"\n        \"c=b'argus-d320-test'\\n\"\n        \"u=struct.pack('!HHHH',40320,40321,8+len(c),0)+c\\n\"\n        \"i=struct.pack('!BBHHHBBH4s4s',0x45,0,20+len(u),0,0,64,17,0,socket.inet_aton(sys.argv[1]),socket.inet_aton(sys.argv[2]))\\n\"\n        \"[s.sendto(i+u,(sys.argv[2],0)) for _ in range(10)]\\n\";\n    FILE* f = std::fopen(\"/tmp/tas320_manda.py\", \"w\");\n    if (f) {\n        std::fputs(py.c_str(), f);\n        std::fclose(f);\n    }\n    sh(std::string(en_raiz ? \"\" : \"ip netns exec \" + NS + \" \") + \"python3 -I /tmp/tas320_manda.py \" + src + \" \" +\n       (en_raiz ? \"127.0.0.1\" : \"10.251.0.1\"));\n    ::usleep(300000);\n}\n\nint main() {\n    if (::geteuid() != 0) {\n        std::cout << \"SALTADO: requiere root (make test-firewall-e2e PROFILE=...)\" << std::endl;\n        return 77;\n    }\n    limpiar();\n    const bool sin_ipmac_permitido = std::getenv(\"ARGUS_TEST_SIN_IPMAC\") != nullptr;\n    const bool con_mac = sh(\"ipset create \" + S_MAC + \" hash:ip,mac counters && echo SI\").find(\"SI\") != std::string::npos;\n    if (!con_mac && !sin_ipmac_permitido) {\n        std::cout << \"SALTADO: el kernel no admite hash:ip,mac (el gate de test-firewall-e2e lo cuenta como fallo)\" << std::endl;\n        limpiar();\n        return 77;\n    }\n    if (!con_mac) std::cout << \"AVISO: sin hash:ip,mac (ARGUS_TEST_SIN_IPMAC): no se prueba la MAC\" << std::endl;\n\n    // red de prueba\n    sh(\"ip netns add \" + NS + \" && ip link add \" + VA + \" type veth peer name \" + VB + \" && ip link set \" + VB + \" netns \" + NS +\n       \" && ip addr add 10.251.0.1/30 dev \" + VA + \" && ip link set \" + VA + \" up && ip -n \" + NS + \" addr add 10.251.0.2/30 dev \" +\n       VB + \" && ip -n \" + NS + \" link set \" + VB + \" up && ip -n \" + NS + \" link set lo up\");\n    sh(\"ip route add 192.168.100.21/32 dev \" + VA + \"; ip route add 192.168.100.22/32 dev \" + VA);\n    std::string macb = sh(\"ip netns exec \" + NS + \" cat /sys/class/net/\" + VB + \"/address\");\n    while (!macb.empty() && (macb.back() == '\\n' || macb.back() == '\\r')) macb.pop_back();\n    sh(\"ip netns exec \" + NS + \" ping -c1 -W1 10.251.0.1 >/dev/null 2>&1\");\n    const std::string ifl = IPTablesWrapper::interfaz_de_ruta(\"192.168.100.20\");\n    CHECK(!ifl.empty() && macb.size() == 17 && IPTablesWrapper::interfaz_de_ruta(\"192.168.100.21\") == VA);\n\n    IPSetWrapper ipset;\n    IPTablesWrapper ipt;\n    CHECK(ipset.create_set(config_set_protegidos(S_IF, 4096)));\n    const std::vector<EntradaAntispoof> ent{{\"192.168.100.20/32\", ifl, \"\"},\n                                            {\"192.168.100.21/32\", VA, MAL_MAC},\n                                            {\"192.168.100.22/32\", VA, macb},\n                                            {\"192.168.100.23/32\", VA, \"\"}};\n    std::vector<std::pair<std::string, std::string>> esp_if;\n    for (const auto& e : ent) esp_if.emplace_back(e.cidr, e.iface);\n    CHECK(ipset.replace_net_iface(S_IF, esp_if, 4096));\n    const auto rep = repartir_antispoof(ent, [](const std::string& ip) { return IPTablesWrapper::interfaz_de_ruta(ip); });\n    NombresAntispoof n{CH, S_RED, S_IF, S_IPM, S_MAC, 5, 5, con_mac};\n    auto spoof = [&](const std::string& suf) {\n        const auto v = ipt.contadores(CH + suf, IPTablesTable::RAW);\n        return v.size() >= 2 ? v[1] : static_cast<uint64_t>(-1);\n    };\n\n    // A1\n    {\n        const auto r = antispoof_paso(ipset, ipt, n, rep, false, 4096, false);\n        CHECK(r.reconciliado && r.error.empty());\n        const auto r2 = antispoof_paso(ipset, ipt, n, rep, false, 4096, true);\n        CHECK(!r2.divergente && r2.reconciliado);\n    }\n    // A6 (el reparto): .23 fuera por la ruta\n    CHECK(rep.sin_ruta.size() == 1 && rep.sin_ruta[0].find(\"192.168.100.23/32\") == 0 && rep.redes.size() == 3);\n    // A2..A6\n    uint64_t i0 = spoof(\"_IF\"), m0 = spoof(\"_MAC\");\n    manda(\"10.251.0.2\");\n    CHECK(spoof(\"_IF\") == i0 && spoof(\"_MAC\") == m0);\n    manda(\"192.168.100.20\");\n    CHECK(spoof(\"_IF\") == i0 + 10 && spoof(\"_MAC\") == m0);\n    if (con_mac) {\n        manda(\"192.168.100.21\");\n        CHECK(spoof(\"_MAC\") == m0 + 10 && spoof(\"_IF\") == i0 + 10);\n    }\n    i0 = spoof(\"_IF\");\n    m0 = spoof(\"_MAC\");\n    manda(\"192.168.100.22\");\n    manda(\"192.168.100.23\");\n    CHECK(spoof(\"_IF\") == i0 && spoof(\"_MAC\") == m0);\n    // A7 lo\n    manda(\"192.168.100.20\", true);\n    CHECK(spoof(\"_IF\") == i0);\n    // A8 modo descarta\n    {\n        const auto r = antispoof_paso(ipset, ipt, n, rep, true, 4096, true);\n        CHECK(r.divergente && r.reconciliado);\n        sh(\"iptables -w -t mangle -I PREROUTING 1 -i \" + VA + \" -s 192.168.100.20 -m comment --comment tas320-llegan\");\n        const uint64_t d0 = spoof(\"_IF\");\n        manda(\"192.168.100.20\");\n        const std::string ll = sh(\"iptables -w -t mangle -L PREROUTING -v -x -n | awk '/tas320-llegan/ {print $1}'\");\n        CHECK(spoof(\"_IF\") == d0 + 10 && std::strtoull(ll.c_str(), nullptr, 10) == 0);\n    }\n    // A9 alguien borra la regla de lo\n    sh(\"iptables -w -t raw -D \" + CH + \" 1\");\n    {\n        const auto r = antispoof_paso(ipset, ipt, n, rep, true, 4096, true);\n        CHECK(r.divergente && r.reconciliado);\n        CHECK(ipt.list_rules(CH, IPTablesTable::RAW) == reglas_esperadas_principal(n));\n    }\n    // A10\n    limpiar();\n    CHECK(sh(\"iptables -w -t raw -S\").find(CH) == std::string::npos && !ipset.set_type(S_RED).has_value() &&\n          sh(\"ip netns list\").find(NS) == std::string::npos);\n    std::cout << \"test_protegidos_antispoof_root: \" << (g_total - g_fallos) << \"/\" << g_total << \" comprobaciones\"\n              << (con_mac ? \"\" : \" (sin MAC)\") << std::endl;\n    return g_fallos == 0 ? 0 : 1;\n}\n",
  "modo": 420
 },
 {
  "ruta": "scripts/etcd_ha/d320_manda_udp.py",
  "antes": null,
  "despues": "8828ca29f4261d6bf2dd7700e9059368753d6a7852cfeac9033fcb3c48fdd88e",
  "nuevo_b64": null,
  "contenido": "#!/usr/bin/env python3\n# [PROTEGIDOS-ANTISPOOF-D320] ADR-060 8e.4b: manda N paquetes UDP con el ORIGEN que se le dé (socket raw, IP_HDRINCL),\n# para probar el antispoofing. Uso (root): python3 -I d320_manda_udp.py ORIGEN DESTINO N\n# Lo usan d320_antispoof_e2e.sh (en el client y en un netns del defender) y la misma técnica que d320_medir_antispoof.sh.\nimport socket\nimport struct\nimport sys\n\nif len(sys.argv) != 4:\n    print(\"uso: d320_manda_udp.py ORIGEN DESTINO N\", file=sys.stderr)\n    sys.exit(2)\nsrc, dst, n = sys.argv[1], sys.argv[2], int(sys.argv[3])\nif not 1 <= n <= 10000:\n    print(\"N en [1, 10000]\", file=sys.stderr)\n    sys.exit(2)\ns = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_RAW)\ncarga = b\"argus-d320-antispoof\"\nudp = struct.pack(\"!HHHH\", 40320, 40321, 8 + len(carga), 0) + carga\nip = struct.pack(\"!BBHHHBBH4s4s\", 0x45, 0, 20 + len(udp), 0, 0, 64, 17, 0, socket.inet_aton(src), socket.inet_aton(dst))\nfor _ in range(n):\n    s.sendto(ip + udp, (dst, 0))\nprint(f\"enviados {n} UDP {src} -> {dst}\")\n",
  "modo": 493
 },
 {
  "ruta": "scripts/etcd_ha/d320_antispoof_e2e.sh",
  "antes": null,
  "despues": "db337c732a02b67ee64c7ca0784322af2844ee9a26353e003935afeb00b99c2e",
  "nuevo_b64": null,
  "contenido": "#!/usr/bin/env bash\n# [PROTEGIDOS-ANTISPOOF-D320] DAY320 E2E del antispoofing (ADR-060 D8, paso 8e.4b) con la MITIGACIÓN REAL.\n# Conmutador SOLO durante la prueba: operation.dry_run=false, ddos_mitigacion.habilitada=true y la escalera de prueba\n# [60, 120] de d302 (modo descarta). Entrada de prueba en el manifiesto, firmada con argus-infra en la VM etcd:\n# 192.168.100.62/32 por eth2 con una MAC que no es la de nadie (02:00:00:00:d3:20); se quita en el trap (dos versiones\n# firmadas por corrida). .20 (VM etcd) no se toca.\n#   S1 el client manda 20 UDP con origen .62 (entra por eth2 con la MAC del client): SPOOF-MAC +20, 0 llegan a mangle\n#   S2 un netns del defender manda 20 UDP con origen .20 por un veth: SPOOF-IF +20, 0 llegan a mangle\n#   S3 en toda la corrida el spoofing contado es exactamente lo inyectado (el tráfico legítimo de .20 suma 0) y su\n#      entrada del set de protegidos sube (su tráfico llega); la VM etcd sigue sana\n#   S4 evidencia en el journal (ARGUS-SPOOF-IF y -MAC), [PROTEGIDOS-SPOOFING] en el log del firewall, sin\n#      [PROTEGIDOS-RUTA] ni [PROTEGIDOS-VIGIA] ERROR\n# trap: quita .62 del manifiesto, para el pipeline, retira cadenas (filter y raw), sets, netns y reglas de cuenta, y\n# restaura el JSON byte a byte (cmp).\n# Uso (raiz del repo, Mac; VMs client y etcd arriba): DIA=day320 bash scripts/etcd_ha/d320_antispoof_e2e.sh NOMBRE\n#\n# PREDICCIÓN (escrita antes de la corrida): S1-S4 PASA; el antispoofing se aplica en modo descarta con redes=3\n# (.20, .61, .62), ips_mac=1, mac=1 y sin_ruta=0.\nset -u\nN=${1:?nombre de la corrida}\nexport DIA=${DIA:-day320}\nH=/vagrant/scripts/timebase/lab_corrida_defender.sh\nU=/vagrant/scripts/etcd_ha/d320_manda_udp.py\nDM=logs/lab/$DIA/$N\nJSON=firewall-acl-agent/config/firewall.json\nBAK=/tmp/$N.firewall.json.orig\nF=logs/lab/firewall-agent.log\nIP62=192.168.100.62; MAL=02:00:00:00:d3:20\nNS=argas320e; VA=ase0; VB=ase1\nWL=\"\"; BL=\"\"; CHAIN=\"\"; AS=\"\"; SR=\"\"; SI=\"\"; SM=\"\"; K=30\nJSON_TOCADO=0; RESTAURADO=0; FALLOS=0; ENTRADA62=0\npaso()  { echo; echo \"=== [$(date +%T)] $*\"; }\nfalla() { echo; echo \"PARADA [$(date +%T)]: $*\"; exit 1; }\npasa()  { echo \"PASA  $*\"; }\nmal()   { echo \"FALLA $*\"; FALLOS=$((FALLOS + 1)); }\nvm()    { vagrant ssh \"$1\" -c \"$2\" 2>/dev/null | tr -d '\\r' | grep -v '^\\[argus\\]'; }\ninfra() { vm etcd \"sudo /usr/local/sbin/argus-infra $1\"; }\ncuenta(){ vm defender \"sudo iptables -w -t raw -L $1 -v -x -n 2>/dev/null | awk 'NR == 4 {print \\$1}'\"; }   # regla 2 = la de cuenta\nllegan(){ vm defender \"sudo iptables -w -t mangle -L PREROUTING -v -x -n | awk '/$1/ {print \\$1}'\"; }\nrestaurar() {\n  [ \"$RESTAURADO\" = 1 ] && return 0\n  RESTAURADO=1\n  echo; echo \"=== [$(date +%T)] TRAP: restaurando el lab\"\n  if [ \"$ENTRADA62\" = 1 ]; then\n    infra \"del --planta lab-vagrant --cidr $IP62/32 --interfaz eth2 --motivo 'fin de la prueba antispoof DAY320' --si\" | tail -n 3\n  fi\n  make pipeline-stop > \"/tmp/${N}_stop_trap.txt\" 2>&1\n  echo \"    pipeline-stop rc=$?\"\n  vm defender \"sudo ip netns del $NS 2>/dev/null; sudo ip link del $VA 2>/dev/null; sudo iptables -w -t mangle -D PREROUTING -i eth2 -s $IP62 -m comment --comment d320as-62 2>/dev/null; sudo iptables -w -t mangle -D PREROUTING -i $VA -s 192.168.100.20 -m comment --comment d320as-20 2>/dev/null; true\" > /dev/null\n  if [ -n \"$AS\" ]; then\n    vm defender \"while sudo iptables -w -t raw -D PREROUTING -j $AS 2>/dev/null; do :; done; for c in $AS ${AS}_IF ${AS}_MAC; do sudo iptables -w -t raw -F \\$c 2>/dev/null; done; for c in $AS ${AS}_IF ${AS}_MAC; do sudo iptables -w -t raw -X \\$c 2>/dev/null; done; while sudo iptables -D INPUT -j $CHAIN 2>/dev/null; do :; done; sudo iptables -F $CHAIN 2>/dev/null; sudo iptables -X $CHAIN 2>/dev/null; for s in $SR $SI $SM $BL $WL; do sudo ipset destroy \\$s 2>/dev/null; done; echo \\\"    quedan raw=\\$(sudo iptables -w -t raw -S | grep -c $AS) filter=\\$(sudo iptables -S | grep -c $CHAIN) sets=\\$(sudo ipset list -n | grep -c -x -e $SR -e $SI -e $SM -e $BL -e $WL)\\\"\"\n  fi\n  if [ \"$JSON_TOCADO\" = 1 ] && [ -f \"$BAK\" ]; then\n    cp \"$BAK\" \"$JSON\"\n    if cmp -s \"$BAK\" \"$JSON\"; then echo \"    JSON restaurado (cmp 0)\"; else echo \"    ERROR: el JSON NO coincide con $BAK\"; fi\n  fi\n  echo \"    el pipeline queda PARADO (como d302); make pipeline-start PROFILE=production para levantarlo\"\n}\ntrap restaurar EXIT\ntrap 'exit 130' INT TERM\n\npaso \"1 comprobaciones previas y nombres\"\ngit diff --quiet -- \"$JSON\" || falla \"$JSON tiene cambios sin commit: no se toca\"\nfor v in client etcd; do vagrant status \"$v\" 2>/dev/null | grep -qE \"^$v +running\" || falla \"la VM $v no está arriba (vagrant up $v)\"; done\nread -r WL BL CHAIN AS SR SI SM K < <(python3 - \"$JSON\" <<'PYEOF'\nimport json, sys\nd = json.load(open(sys.argv[1], encoding=\"utf-8\"))\np = d.get(\"protegidos\", {}); a = p.get(\"antispoof\", {})\nprint(p.get(\"set_name\", \"ml_defender_protegidos\"), d[\"ipsets\"][\"blacklist\"][\"set_name\"], d[\"iptables\"][\"chain_name\"],\n      a.get(\"cadena\", \"ARGUS_ANTISPOOF\"), a.get(\"set_redes\", \"ml_defender_prot_redes\"),\n      a.get(\"set_ips_mac\", \"ml_defender_prot_ipmac\"), a.get(\"set_mac\", \"ml_defender_prot_mac\"),\n      p.get(\"comprobacion_kernel_sec\", 30))\nPYEOF\n) || falla \"no leo el JSON\"\nLIM=$((K + 5))\necho \"    cadena raw=$AS sets=$SR,$SI,$SM protegidos=$WL K=$K s\"\nmkdir -p \"$DM\"\nvm client \"ip neigh show 192.168.100.1 dev eth1 | grep -q lladdr\" || falla \"el client no tiene la MAC de .1 (make lab-e2e-prep)\"\n\npaso \"2 entrada de prueba $IP62 por eth2 con MAC $MAL (argus-infra, VM etcd)\"\ninfra \"add --planta lab-vagrant --categoria intranet --cidr $IP62/32 --interfaz eth2 --mac $MAL --motivo-entrada 'prueba antispoof DAY320' --motivo 'prueba antispoof DAY320 (se quita al acabar)' --si\" | tail -n 4\ninfra \"list\" | grep -q \"$IP62/32\" || falla \"argus-infra no publicó $IP62\"\nENTRADA62=1\n\npaso \"3 pipeline-stop y conmutador SOLO para la prueba (copia exacta en $BAK)\"\nmake pipeline-stop > \"/tmp/${N}_stop0.txt\" 2>&1 || falla \"pipeline-stop\"\nrm -f \"$BAK\"; cp \"$JSON\" \"$BAK\" || falla \"copia del JSON\"\nJSON_TOCADO=1\npython3 - \"$JSON\" <<'PYEOF' || falla \"no se pudo conmutar el JSON\"\nimport json, sys\np = sys.argv[1]\nd = json.load(open(p, encoding=\"utf-8\"))\nd[\"operation\"][\"dry_run\"] = False\nd[\"ddos_mitigacion\"][\"habilitada\"] = True\nd[\"recidivism\"][\"strike_durations_sec\"] = [60, 120]\nwith open(p, \"w\", encoding=\"utf-8\") as f:\n    json.dump(d, f, indent=2, ensure_ascii=False)\n    f.write(\"\\n\")\nprint(\"    ahora: dry_run=False habilitada=True escalera=[60, 120] (PRUEBA)\")\nPYEOF\n\npaso \"4 logs a cero y pipeline-start PROFILE=production\"\nvm defender \"DIA=$DIA bash $H truncar\" > /dev/null || falla \"truncar\"\nmake pipeline-start PROFILE=production > \"/tmp/${N}_start.txt\" 2>&1 || { tail -n 20 \"/tmp/${N}_start.txt\"; falla \"pipeline-start rc!=0\"; }\n\npaso \"5 antispoofing en modo descarta con la entrada de prueba (máximo 120 s)\"\nok=0\nfor i in $(seq 1 120); do\n  if grep -E \"\\[PROTEGIDOS-ANTISPOOF\\] aplicado .*modo=descarta redes=3 ips_mac=1 mac=1\" \"$F\" > /dev/null 2>&1 && \\\n     vm defender \"sudo ipset save $SM | grep -qi '$IP62,$MAL'\"; then ok=1; break; fi\n  sleep 1\ndone\ngrep \"\\[PROTEGIDOS-ANTISPOOF\\]\" \"$F\" | tail -n 3\n[ \"$ok\" = 1 ] || falla \"no aparece el antispoofing en modo descarta con redes=3 ips_mac=1 mac=1 y $IP62 en $SM\"\nvm defender \"sudo iptables -w -t raw -S PREROUTING | sed -n 2p; sudo iptables -w -t raw -S $AS; sudo iptables -w -t raw -S ${AS}_MAC\" | sed 's/^/    /'\nI0=$(cuenta \"${AS}_IF\"); M0=$(cuenta \"${AS}_MAC\")\nP0=$(vm defender \"sudo ipset save $WL | awk '\\$3 ~ /^192\\\\.168\\\\.100\\\\.20,/ {for (i = 4; i < NF; i++) if (\\$i == \\\"packets\\\") print \\$(i + 1)}'\")\necho \"    contadores al empezar: spoof_if=$I0 spoof_mac=$M0; .20 en $WL=$P0 paquetes\"\nT0=$(vm defender \"date '+%Y-%m-%d %H:%M:%S'\")\n\npaso \"6 S1 el client manda 20 UDP con origen $IP62 (MAC del client)\"\nvm defender \"sudo iptables -w -t mangle -I PREROUTING 1 -i eth2 -s $IP62 -m comment --comment d320as-62\" > /dev/null\nvm client \"sudo python3 -I $U $IP62 192.168.100.1 20\"\nsleep 2\nM1=$(cuenta \"${AS}_MAC\"); L62=$(llegan d320as-62)\n[ \"$((M1 - M0))\" = 20 ] && [ \"${L62:-x}\" = 0 ] && pasa \"S1 SPOOF-MAC +$((M1 - M0)), llegan a mangle $L62\" || mal \"S1 SPOOF-MAC +$((M1 - M0)) (esperado 20), llegan a mangle ${L62:-?} (esperado 0)\"\n\npaso \"7 S2 un netns del defender manda 20 UDP con origen .20 por un veth\"\nvm defender \"sudo ip netns add $NS && sudo ip link add $VA type veth peer name $VB && sudo ip link set $VB netns $NS && sudo ip addr add 10.252.0.1/30 dev $VA && sudo ip link set $VA up && sudo ip -n $NS addr add 10.252.0.2/30 dev $VB && sudo ip -n $NS link set $VB up && sudo ip netns exec $NS ping -c1 -W1 10.252.0.1 > /dev/null; sudo iptables -w -t mangle -I PREROUTING 1 -i $VA -s 192.168.100.20 -m comment --comment d320as-20\" > /dev/null\nI1a=$(cuenta \"${AS}_IF\")\nvm defender \"sudo ip netns exec $NS python3 -I $U 192.168.100.20 10.252.0.1 20\"\nsleep 2\nI1=$(cuenta \"${AS}_IF\"); L20=$(llegan d320as-20)\n[ \"$((I1 - I1a))\" = 20 ] && [ \"${L20:-x}\" = 0 ] && pasa \"S2 SPOOF-IF +$((I1 - I1a)), llegan a mangle $L20\" || mal \"S2 SPOOF-IF +$((I1 - I1a)) (esperado 20), llegan a mangle ${L20:-?} (esperado 0)\"\n\npaso \"8 S3 el tráfico legítimo de .20 no cuenta (70 s, chrony de la VM etcd cada 64 s)\"\nsleep 70\nI2=$(cuenta \"${AS}_IF\"); M2=$(cuenta \"${AS}_MAC\")\nP2=$(vm defender \"sudo ipset save $WL | awk '\\$3 ~ /^192\\\\.168\\\\.100\\\\.20,/ {for (i = 4; i < NF; i++) if (\\$i == \\\"packets\\\") print \\$(i + 1)}'\")\n[ \"$((I2 - I0))\" = 20 ] && [ \"$((M2 - M0))\" = 20 ] && [ \"${P2:-0}\" -gt \"${P0:-0}\" ] \\\n  && pasa \"S3 spoofing contado = inyectado (interfaz +$((I2 - I0)), mac +$((M2 - M0))); .20 legítima $P0 -> $P2 paquetes\" \\\n  || mal \"S3 interfaz +$((I2 - I0)) mac +$((M2 - M0)) (esperado 20 y 20); .20 legítima ${P0:-?} -> ${P2:-?}\"\nmake pipeline-status > \"/tmp/${N}_status.txt\" 2>&1\ngrep -q \"etcd-server:   RUNNING\" \"/tmp/${N}_status.txt\" && pasa \"S3 la VM etcd sigue sana (pipeline-status)\" || { mal \"S3 etcd-server no RUNNING\"; grep etcd \"/tmp/${N}_status.txt\"; }\n\npaso \"9 S4 evidencia y log\"\nJI=$(vm defender \"sudo journalctl -k --since '$T0' --no-pager | grep -c 'ARGUS-SPOOF-IF '\")\nJM=$(vm defender \"sudo journalctl -k --since '$T0' --no-pager | grep -c 'ARGUS-SPOOF-MAC '\")\n[ \"${JI:-0}\" -ge 1 ] && [ \"${JM:-0}\" -ge 1 ] && pasa \"S4 journal: ARGUS-SPOOF-IF=$JI ARGUS-SPOOF-MAC=$JM\" || mal \"S4 journal: IF=${JI:-?} MAC=${JM:-?} (esperado >= 1 cada una)\"\nvm defender \"sudo journalctl -k --since '$T0' --no-pager | grep -m 1 'ARGUS-SPOOF-MAC '\" | cut -c1-220 | sed 's/^/    /'\nns=$(grep -c \"\\[PROTEGIDOS-SPOOFING\\]\" \"$F\"); nr=$(grep -c \"\\[PROTEGIDOS-RUTA\\]\" \"$F\"); ne=$(grep -c \"\\[PROTEGIDOS-VIGIA\\] ERROR\" \"$F\")\ngrep \"\\[PROTEGIDOS-SPOOFING\\]\" \"$F\" | tail -n 2 | sed 's/^/    /'\n[ \"$ns\" -ge 1 ] && [ \"$nr\" = 0 ] && [ \"$ne\" = 0 ] && pasa \"S4 [PROTEGIDOS-SPOOFING]=$ns, [PROTEGIDOS-RUTA]=0, ERROR=0\" || mal \"S4 SPOOFING=$ns RUTA=$nr ERROR=$ne (esperado >=1, 0, 0)\"\ncp \"$F\" \"$DM/firewall-agent.log\" 2>/dev/null\necho; echo \"=== RESULTADO $([ \"$FALLOS\" = 0 ] && echo PASA || echo \"FALLA ($FALLOS)\") — $DM/\"\n[ \"$FALLOS\" = 0 ]\n",
  "modo": 493
 },
